VALUES ('REP-026', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Jairnilson Paim e Naomar de Almeida Filho', NULL, 'PESQUISADORES / SANITARISTAS', 'Saúde coletiva', 'Brasil', 'Autores centrais na formulação conceitual da saúde coletiva brasileira. A abordagem considera o processo saúde-doença-cuidado em sua historicidade e integralidade, articulando dimensões sociais, políticas e institucionais.', 'Saúde coletiva não é apenas assistência médica: analisa saúde-doença-cuidado como fenômeno histórico e social, ligado a políticas, condições de vida e organização do sistema.', 'Use quando o tema exigir mostrar que saúde pública depende de condições sociais e organização coletiva do cuidado.', 'A perspectiva da saúde coletiva desenvolvida por Paim e Almeida Filho ajuda a superar uma visão exclusivamente biomédica, pois entende o cuidado como fenômeno também social, histórico e político.', 'Não atribuir aos autores a ideia de que fatores biológicos são irrelevantes.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 4, 5, 3, 4, 5, 5, '["DEFINE_CONCEPT", "EXPLAIN_CAUSE", "HISTORICAL_CONTEXT"]'::jsonb, '["necessidade de políticas públicas integradas", "limites do modelo puramente biomédico"]'::jsonb, '["SUS", "acesso à saúde", "prevenção", "determinantes sociais", "políticas de saúde"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
