VALUES ('REP-027', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Magda Soares', NULL, 'EDUCADORA / PESQUISADORA', 'Alfabetização, leitura e letramento', 'Brasil', 'Distinguiu e articulou alfabetização e letramento: dominar o sistema de escrita não equivale, por si só, a participar competentemente das práticas sociais de leitura e escrita.', 'Alfabetizar é ensinar o sistema de escrita; letrar envolve usar leitura e escrita em práticas sociais. Uma política educacional de qualidade precisa articular as duas dimensões.', 'Use para discutir por que acesso formal à escola ou decodificação de palavras não garantem plena participação na cultura escrita.', 'A distinção proposta por Magda Soares entre alfabetização e letramento mostra que aprender o código escrito não basta quando o estudante não desenvolve condições de utilizar leitura e escrita em situações sociais concretas.', 'Não tratar alfabetização e letramento como opostos; na autora, são processos distintos, porém articulados.', 'MEDIUM', 'BASIC', 'MEDIUM', 4, 5, 5, 5, 5, 4, '["DEFINE_CONCEPT", "EXPLAIN_CAUSE", "SUPPORT_INTERVENTION"]'::jsonb, '["falha educacional", "ensino descontextualizado", "formação docente"]'::jsonb, '["alfabetização", "analfabetismo funcional", "desigualdade educacional", "formação docente"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
