VALUES ('REP-028', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Miguel Arroyo', NULL, 'EDUCADOR / PESQUISADOR', 'Direito à educação, sujeitos populares e movimentos sociais', 'Brasil', 'Sua produção enfatiza que grupos historicamente excluídos são sujeitos de direitos e de conhecimentos; a escola deve reconhecer trajetórias, identidades e saberes dos setores populares.', 'Arroyo ajuda a pensar educação como direito de sujeitos historicamente excluídos, e não como favor ou simples adaptação desses grupos a um padrão escolar dominante.', 'Use em temas de acesso/permanência quando o problema envolve grupos cujas experiências são pouco reconhecidas pela escola.', 'A perspectiva de Miguel Arroyo evidencia que assegurar o direito à educação também exige reconhecer como legítimos os saberes e trajetórias de grupos historicamente afastados da escola.', 'Não reduzir sua obra a uma defesa genérica de inclusão sem mencionar sujeitos, direitos e reconhecimento.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 4, 5, 4, 4, 4, 5, '["SOCIAL_CRITIQUE", "SHOW_INVISIBILITY", "SUPPORT_INTERVENTION"]'::jsonb, '["invisibilidade de sujeitos", "barreiras institucionais", "reconhecimento de saberes"]'::jsonb, '["EJA", "educação do campo", "desigualdade educacional", "exclusão", "povos tradicionais"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
