VALUES ('REP-030', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Ricardo Antunes', NULL, 'SOCIÓLOGO / PESQUISADOR', 'Sociologia do trabalho', 'Brasil', 'Analisa transformações do trabalho contemporâneo, terceirização, precarização, jornadas e novas formas de exploração, incluindo a plataformização.', 'Antunes ajuda a interpretar como mudanças tecnológicas e empresariais podem gerar novas formas de precarização, intensificação e insegurança do trabalho.', 'Use para explicar que inovação tecnológica não produz automaticamente melhoria das condições de trabalho.', 'A análise de Ricardo Antunes sobre as transformações do trabalho ajuda a compreender que plataformas digitais podem combinar inovação tecnológica com jornadas intensas e menor proteção social.', 'Não apresentar toda tecnologia como necessariamente precarizante; o argumento deve tratar das relações de trabalho concretas.', 'MEDIUM', 'INTERMEDIATE', 'MEDIUM', 4, 5, 4, 5, 4, 4, '["EXPLAIN_CAUSE", "SOCIAL_CRITIQUE", "SHOW_INEQUALITY"]'::jsonb, '["precarização", "assimetria entre empresa e trabalhador", "desproteção"]'::jsonb, '["uberização", "terceirização", "jornada", "precarização", "automação"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
