VALUES ('REP-031', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Ludmila Costhek Abílio', NULL, 'SOCIOLOGA / PESQUISADORA', 'Trabalho por plataformas e uberização', 'Brasil', 'Pesquisa a uberização e processos de informalização, destacando formas de gestão e controle do trabalho mediadas por plataformas e a transferência de riscos para trabalhadores.', 'Na uberização, o trabalhador parece autônomo, mas pode continuar submetido a formas de controle, avaliação e gestão algorítmica, assumindo custos e riscos da atividade.', 'Use em temas de trabalho algorítmico para ir além da oposição simplista entre emprego formal e autonomia.', 'As pesquisas de Ludmila Abílio mostram que a aparente autonomia do trabalho por plataformas pode coexistir com formas intensas de controle e com a transferência de custos e riscos para o próprio trabalhador.', 'Não usar uberização como sinônimo de qualquer trabalho informal.', 'HIGH', 'INTERMEDIATE', 'LOW', 3, 5, 4, 5, 5, 5, '["DEFINE_CONCEPT", "EXPLAIN_CAUSE", "SOCIAL_CRITIQUE"]'::jsonb, '["autonomia subordinada", "transferência de riscos", "precarização"]'::jsonb, '["trabalho por aplicativos", "entregadores", "informalidade", "gestão algorítmica"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
