VALUES ('REP-032', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Helena Hirata', NULL, 'SOCIÓLOGA / PESQUISADORA', 'Trabalho, gênero e cuidado', 'Brasil/França', 'Analisa divisão sexual do trabalho e relações de cuidado, mostrando como gênero, raça e classe se articulam nas trajetórias de cuidadoras.', 'O trabalho de cuidado é indispensável, mas recai de forma desigual sobre mulheres; gênero, raça e classe estruturam quem cuida, em quais condições e com qual reconhecimento.', 'Use para mostrar que cuidado não é apenas uma escolha familiar privada, mas uma relação social com distribuição desigual.', 'Os estudos de Helena Hirata evidenciam que o cuidado, embora essencial à vida social, é distribuído de forma desigual e permanece fortemente associado ao trabalho feminino e às hierarquias de classe e raça.', 'Não afirmar que todo trabalho de cuidado é necessariamente não remunerado.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 4, 5, 4, 5, 5, 5, '["EXPLAIN_CAUSE", "SHOW_INEQUALITY", "SOCIAL_CRITIQUE"]'::jsonb, '["divisão sexual do trabalho", "desvalorização do cuidado", "interseccionalidade"]'::jsonb, '["trabalho de cuidado", "envelhecimento", "trabalho doméstico", "desigualdade de gênero"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
