VALUES ('REP-033', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Fernando Braga da Costa', NULL, 'PSICÓLOGO SOCIAL / PESQUISADOR', 'Invisibilidade pública e trabalho', 'Brasil', 'Investigou a invisibilidade pública por meio de pesquisa etnográfica com garis, trabalhando como gari semanalmente durante anos. O conceito descreve uma forma de apagamento social de pessoas em posições subalternizadas.', 'Invisibilidade pública: certos trabalhadores são fisicamente vistos, mas socialmente ignorados; a posição ocupada pode produzir apagamento e falta de reconhecimento.', 'Use quando o problema envolver grupos presentes no cotidiano, mas pouco reconhecidos como sujeitos sociais.', 'A pesquisa de Fernando Braga da Costa com garis mostra que a exclusão pode assumir a forma de invisibilidade pública, quando determinados trabalhadores são percebidos apenas por sua função e deixam de ser reconhecidos como sujeitos.', 'Não afirmar que sua pesquisa original foi sobre população em situação de rua.', 'MEDIUM', 'BASIC', 'LOW', 4, 5, 5, 5, 5, 5, '["SHOW_INVISIBILITY", "DEFINE_CONCEPT", "SOCIAL_CRITIQUE"]'::jsonb, '["invisibilidade social", "desrespeito", "hierarquização do trabalho"]'::jsonb, '["trabalhadores invisibilizados", "população em situação de rua", "estigma", "desigualdade"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
