VALUES ('REP-034', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Kabengele Munanga', NULL, 'ANTROPÓLOGO / PESQUISADOR', 'Racismo, identidade negra e relações étnico-raciais', 'Brasil / RD Congo', 'Estuda racismo, negritude, identidade negra, multiculturalismo e educação das relações étnico-raciais, discutindo como categorias raciais foram historicamente construídas e podem operar socialmente.', 'Munanga ajuda a explicar que raça não tem fundamento biológico como hierarquia humana, mas continua produzindo efeitos sociais por meio do racismo, da identidade e das relações históricas.', 'Use para diferenciar a inexistência de raças biológicas humanas da existência social do racismo.', 'A produção de Kabengele Munanga permite compreender que, embora hierarquias raciais não possuam base biológica, a ideia de raça foi historicamente construída e continua produzindo consequências sociais concretas.', 'Não dizer que o autor defende raça como categoria biológica.', 'HIGH', 'INTERMEDIATE', 'MEDIUM', 4, 5, 4, 5, 5, 4, '["HISTORICAL_CONTEXT", "DEFINE_CONCEPT", "SOCIAL_CRITIQUE"]'::jsonb, '["construção social da raça", "racismo", "reconhecimento identitário"]'::jsonb, '["racismo", "identidade", "educação antirracista", "ações afirmativas"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
