VALUES ('REP-035', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Nilma Lino Gomes', NULL, 'EDUCADORA / ANTROPÓLOGA', 'Educação, relações étnico-raciais e identidade', 'Brasil', 'Pesquisa educação, diversidade, relações raciais, formação docente, políticas educacionais e movimento negro, mostrando como identidade e desigualdade racial também são produzidas e contestadas em espaços educativos.', 'Nilma Lino Gomes conecta educação, identidade negra, formação docente, movimentos sociais e políticas de igualdade racial.', 'Use quando a escola aparece não apenas como solução, mas também como espaço que pode reproduzir ou enfrentar desigualdades raciais.', 'As pesquisas de Nilma Lino Gomes mostram que a educação participa da construção de identidades e pode tanto reproduzir discriminações quanto criar práticas de reconhecimento e valorização da diversidade racial.', 'Não reduzir sua obra exclusivamente a cotas universitárias.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 5, 5, 4, 5, 5, 5, '["SHOW_INEQUALITY", "SOCIAL_CRITIQUE", "SUPPORT_INTERVENTION"]'::jsonb, '["racismo institucional", "invisibilidade curricular", "reconhecimento"]'::jsonb, '["racismo escolar", "identidade negra", "formação docente", "currículo", "ações afirmativas"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
