VALUES ('REP-036', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Débora Diniz e o modelo social da deficiência', NULL, 'PESQUISADORA / CONCEITO', 'Deficiência, bioética e direitos humanos', 'Brasil', 'No campo dos estudos da deficiência, a abordagem social desloca o foco exclusivo do corpo individual para as barreiras sociais, políticas e ambientais que produzem exclusão.', 'Deficiência não pode ser compreendida apenas como lesão ou diagnóstico; barreiras sociais e institucionais participam da produção da desvantagem.', 'Use para explicar por que remover barreiras pode ser tão importante quanto oferecer tratamento individual.', 'A abordagem social da deficiência presente nos estudos de Débora Diniz ajuda a mostrar que a exclusão surge também da maneira como instituições e ambientes são organizados.', 'Não negar a existência de dimensões corporais ou necessidades de saúde; o modelo social critica sua transformação em explicação exclusiva da exclusão.', 'HIGH', 'INTERMEDIATE', 'LOW', 4, 5, 4, 5, 5, 5, '["DEFINE_CONCEPT", "EXPLAIN_CAUSE", "SOCIAL_CRITIQUE"]'::jsonb, '["barreiras sociais", "igualdade material", "justiça social"]'::jsonb, '["capacitismo", "acessibilidade", "BPC", "inclusão", "políticas sociais"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
