VALUES ('REP-037', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Izabel Maior', NULL, 'MÉDICA FISIATRA / ESPECIALISTA', 'Direitos da pessoa com deficiência e acessibilidade', 'Brasil', 'Especialista e ativista histórica em políticas de acessibilidade e direitos da pessoa com deficiência, participou da implementação da abordagem biopsicossocial e da Convenção da ONU no Brasil.', 'Izabel Maior ajuda a conectar acessibilidade, direitos e modelo biopsicossocial: a deficiência deve ser avaliada em interação com barreiras e condições de participação.', 'Use para dar concretude brasileira a temas de políticas de inclusão e avaliação da deficiência.', 'A trajetória de Izabel Maior evidencia como a inclusão depende de políticas que reconheçam a interação entre impedimentos pessoais e barreiras sociais, e não apenas de diagnósticos médicos isolados.', 'Não apresentar a avaliação biopsicossocial como simples substituição do médico por outro profissional.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 3, 5, 4, 4, 5, 5, '["SUPPORT_INTERVENTION", "DEFINE_CONCEPT", "HISTORICAL_CONTEXT"]'::jsonb, '["barreiras institucionais", "implementação de direitos", "acessibilidade"]'::jsonb, '["acessibilidade", "avaliação biopsicossocial", "políticas de deficiência", "participação"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
