INSERT INTO repertorios (codigo, tipo_entidade, papel, tipos_evidencia, nome, subtitulo, tipo_descricao, area, pais, ideia_central, lembre_na_prova, como_usar, exemplo_aplicacao, erro_comum, risco_uso, dificuldade, saturacao, nota_versatilidade, nota_autoridade, nota_compreensao, nota_aplicabilidade, nota_especificidade, nota_originalidade, funcoes_argumentativas, tipos_argumento, tags, populacao, ano_evidencia, status_verificacao, verificado_em, ativo)
VALUES ('REP-038', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Alexandre Kalache', NULL, 'EPIDEMIOLOGISTA / ESPECIALISTA', 'Envelhecimento e longevidade', 'Brasil', 'Referência internacional em envelhecimento, chama atenção para a velocidade da transição demográfica brasileira e para a necessidade de políticas que garantam envelhecimento ativo, saúde e participação.', 'O Brasil envelhece rapidamente; longevidade precisa ser acompanhada de saúde, autonomia, proteção social, cidades e serviços preparados para uma população mais velha.', 'Use para transformar ''envelhecimento populacional'' em debate sobre cidadania e preparação social.', 'Alexandre Kalache destaca que o rápido envelhecimento brasileiro exige adaptação de sistemas de saúde, cuidado e cidades, pois viver mais não garante, sozinho, autonomia e qualidade de vida.', 'Não tratar projeções demográficas antigas como números atuais sem verificar o ano.', 'MEDIUM', 'BASIC', 'LOW', 4, 5, 5, 5, 4, 5, '["PROVE_PROBLEM", "HISTORICAL_CONTEXT", "SUPPORT_INTERVENTION"]'::jsonb, '["despreparo institucional", "transição demográfica", "necessidade de políticas intersetoriais"]'::jsonb, '["etarismo", "cuidado", "saúde da pessoa idosa", "previdência", "cidades amigáveis"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
