VALUES ('REP-039', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Carlos Nobre', NULL, 'CLIMATOLOGISTA / PESQUISADOR', 'Mudanças climáticas e Amazônia', 'Brasil', 'Pesquisador brasileiro de referência em mudanças climáticas. Seu trabalho é útil para fundamentar a dimensão científica da crise climática e discutir riscos sistêmicos.', 'Mudanças climáticas têm fundamento científico robusto; seus impactos tornam-se sociais quando atingem de forma desigual territórios, infraestrutura, saúde e meios de vida.', 'Use para estabelecer a base científica do fenômeno e depois conectá-la à desigualdade social.', 'A produção científica de Carlos Nobre fornece base para compreender a crise climática como fenômeno mensurável, cujos impactos sociais dependem da capacidade desigual de prevenção e adaptação dos territórios.', 'Não atribuir previsão de desastre específico sem fonte.', 'MEDIUM', 'INTERMEDIATE', 'MEDIUM', 4, 5, 4, 5, 5, 4, '["PROVE_PROBLEM", "EXPLAIN_CONSEQUENCE", "SUPPORT_INTERVENTION"]'::jsonb, '["risco climático", "necessidade de adaptação", "prevenção"]'::jsonb, '["eventos extremos", "Amazônia", "adaptação", "justiça climática"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
