VALUES ('REP-040', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Jacqueline Sinhoretto', NULL, 'SOCIÓLOGA / PESQUISADORA', 'Violência, policiamento e justiça criminal', 'Brasil', 'Pesquisa sociologia da violência, punição, segurança pública, policiamento, justiça criminal e prisões, permitindo discutir como instituições administram conflitos e como desigualdades podem aparecer no sistema de segurança.', 'Violência e segurança não são apenas questões de crime individual; também envolvem instituições, policiamento, justiça, punição e desigualdades na administração de conflitos.', 'Use para analisar segurança pública além do senso comum punitivista.', 'As pesquisas de Jacqueline Sinhoretto ajudam a compreender que políticas de segurança devem ser avaliadas também pela forma como policiamento e justiça distribuem proteção, controle e punição entre diferentes grupos sociais.', 'Não transformar análise sociológica em defesa de uma política penal específica.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 4, 5, 4, 4, 5, 5, '["EXPLAIN_CAUSE", "SHOW_INEQUALITY", "SOCIAL_CRITIQUE"]'::jsonb, '["seletividade institucional", "falha de políticas", "desigualdade racial"]'::jsonb, '["violência urbana", "policiamento", "prisões", "seletividade institucional"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
INSERT INTO repertorios (codigo, tipo_entidade, papel, tipos_evidencia, nome, subtitulo, tipo_descricao, area, pais, ideia_central, lembre_na_prova, como_usar, exemplo_aplicacao, erro_comum, risco_uso, dificuldade, saturacao, nota_versatilidade, nota_autoridade, nota_compreensao, nota_aplicabilidade, nota_especificidade, nota_originalidade, funcoes_argumentativas, tipos_argumento, tags, populacao, ano_evidencia, status_verificacao, verificado_em, ativo)
VALUES ('REP-041', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Axel Honneth', 'reconhecimento e invisibilidade social', 'FILÓSOFO / CONCEITO', 'Teoria do reconhecimento', 'Alemanha', 'A invisibilidade social pode ser compreendida como forma simbólica de desrespeito: alguém é fisicamente percebido, mas não reconhecido como sujeito moral e social válido.', 'Para Honneth, invisibilidade social não significa ser literalmente invisível; significa não receber reconhecimento social e moral suficiente para ser tratado como sujeito plenamente válido.', 'Use quando o problema envolve apagamento social e dignidade, combinando bem com Fernando Braga da Costa.', 'A teoria do reconhecimento de Axel Honneth ajuda a interpretar a invisibilidade social como forma de desrespeito, pois determinados indivíduos podem estar presentes no espaço público sem serem efetivamente reconhecidos como sujeitos de igual valor.', 'Não usar ''reconhecimento'' como sinônimo genérico de fama, atenção ou visibilidade midiática.', 'HIGH', 'ADVANCED', 'LOW', 4, 5, 3, 4, 5, 5, '["DEFINE_CONCEPT", "SHOW_INVISIBILITY", "SOCIAL_CRITIQUE"]'::jsonb, '["falta de reconhecimento", "desrespeito", "exclusão simbólica"]'::jsonb, '["invisibilidade", "estigma", "trabalhadores subalternizados", "racismo", "PcD"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
INSERT INTO repertorios (codigo, tipo_entidade, papel, tipos_evidencia, nome, subtitulo, tipo_descricao, area, pais, ideia_central, lembre_na_prova, como_usar, exemplo_aplicacao, erro_comum, risco_uso, dificuldade, saturacao, nota_versatilidade, nota_autoridade, nota_compreensao, nota_aplicabilidade, nota_especificidade, nota_originalidade, funcoes_argumentativas, tipos_argumento, tags, populacao, ano_evidencia, status_verificacao, verificado_em, ativo)
VALUES ('REP-042', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Pierre Bourdieu', 'capital cultural e reprodução das desigualdades', 'SOCIÓLOGO / CONCEITO', 'Educação e desigualdade social', 'França', 'O conceito de capital cultural ajuda a explicar por que recursos culturais valorizados pela escola são distribuídos de maneira desigual entre famílias e classes sociais, influenciando trajetórias escolares.', 'A escola não recebe alunos com os mesmos recursos culturais prévios; quando trata como natural a cultura dos grupos privilegiados, pode transformar desigualdades sociais em desigualdades escolares.', 'Use para contestar explicações que atribuem sucesso escolar somente ao esforço individual.', 'O conceito de capital cultural de Bourdieu ajuda a compreender por que estudantes chegam à escola com recursos desigualmente valorizados, o que torna insuficiente explicar resultados educacionais apenas pelo mérito individual.', 'Não afirmar que a escola sempre reproduz mecanicamente a estrutura social ou que mobilidade é impossível.', 'HIGH', 'ADVANCED', 'HIGH', 5, 5, 3, 5, 5, 2, '["EXPLAIN_CAUSE", "SHOW_INEQUALITY", "DEFINE_CONCEPT"]'::jsonb, '["reprodução de desigualdades", "capital cultural", "meritocracia"]'::jsonb, '["desigualdade educacional", "acesso ao ensino superior", "sucesso/fracasso escolar"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
INSERT INTO repertorios (codigo, tipo_entidade, papel, tipos_evidencia, nome, subtitulo, tipo_descricao, area, pais, ideia_central, lembre_na_prova, como_usar, exemplo_aplicacao, erro_comum, risco_uso, dificuldade, saturacao, nota_versatilidade, nota_autoridade, nota_compreensao, nota_aplicabilidade, nota_especificidade, nota_originalidade, funcoes_argumentativas, tipos_argumento, tags, populacao, ano_evidencia, status_verificacao, verificado_em, ativo)
VALUES ('REP-043', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Paulo Freire', 'educação dialógica e autonomia', 'EDUCADOR / PENSADOR', 'Educação', 'Brasil', 'A educação deve formar sujeitos capazes de compreender criticamente a realidade e participar do processo educativo, em oposição a práticas meramente transmissivas.', 'Freire é mais útil quando ligado a autonomia, diálogo, leitura crítica do mundo e participação do estudante — não como citação genérica sobre educação.', 'Use quando a proposta argumentativa envolve formação crítica e participação ativa do estudante.', 'A pedagogia de Paulo Freire contribui para compreender que a educação cidadã não se limita à transmissão de conteúdos, pois exige diálogo e participação do estudante na construção do conhecimento.', 'Não atribuir frases populares sem fonte; evitar ''educação muda o mundo'' como citação automática.', 'HIGH', 'INTERMEDIATE', 'HIGH', 5, 5, 4, 5, 4, 1, '["DEFINE_CONCEPT", "SUPPORT_INTERVENTION", "SOCIAL_CRITIQUE"]'::jsonb, '["falha educacional", "ausência de participação", "educação emancipatória"]'::jsonb, '["formação cidadã", "alfabetização", "educação de adultos", "ensino autoritário"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
INSERT INTO repertorios (codigo, tipo_entidade, papel, tipos_evidencia, nome, subtitulo, tipo_descricao, area, pais, ideia_central, lembre_na_prova, como_usar, exemplo_aplicacao, erro_comum, risco_uso, dificuldade, saturacao, nota_versatilidade, nota_autoridade, nota_compreensao, nota_aplicabilidade, nota_especificidade, nota_originalidade, funcoes_argumentativas, tipos_argumento, tags, populacao, ano_evidencia, status_verificacao, verificado_em, ativo)
VALUES ('REP-044', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Simone de Beauvoir', 'gênero como construção social', 'FILÓSOFA / CONCEITO', 'Filosofia e estudos de gênero', 'França', 'O Segundo Sexo abriu caminho para pensar a condição feminina como construída social e historicamente, e não explicada apenas pela biologia.', 'Beauvoir ajuda a argumentar que expectativas e papéis atribuídos às mulheres são socialmente construídos e podem sustentar desigualdades.', 'Use quando o argumento precisa mostrar que expectativas sociais sobre mulheres não são inevitáveis nem puramente biológicas.', 'A reflexão de Simone de Beauvoir sobre a construção social da condição feminina permite questionar a naturalização de papéis de cuidado e dependência atribuídos às mulheres.', 'Não transformar a famosa frase da autora em slogan sem contexto; priorize a ideia conceitual.', 'HIGH', 'INTERMEDIATE', 'HIGH', 4, 5, 4, 4, 4, 2, '["DEFINE_CONCEPT", "HISTORICAL_CONTEXT", "SOCIAL_CRITIQUE"]'::jsonb, '["papéis de gênero", "desigualdade estrutural", "naturalização"]'::jsonb, '["desigualdade de gênero", "maternidade", "trabalho", "participação política", "violência simbólica"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
