VALUES ('REP-047', 'CULTURAL_WORK', 'REPERTOIRE', '[]'::jsonb, 'Um Defeito de Cor', 'Ana Maria Gonçalves', 'OBRA LITERÁRIA', 'Literatura, escravidão, memória e identidade negra', 'Brasil', 'Romance histórico brasileiro que permite abordar escravidão, diáspora, violência, memória e protagonismo negro a partir de perspectiva centrada em uma mulher negra.', 'Obra útil para discutir memória da escravidão, protagonismo negro e apagamentos históricos; oferece uma perspectiva que desloca o olhar tradicional sobre a formação do Brasil.', 'Use em temas de memória, cultura afro-brasileira e permanências históricas do racismo.', 'Um Defeito de Cor permite relacionar a memória da escravidão à construção da identidade e ao apagamento de experiências negras, mostrando como disputas de memória também são disputas por reconhecimento.', 'Não tratar o romance como documento histórico literal; é obra literária de base histórica.', 'MEDIUM', 'INTERMEDIATE', 'LOW', 4, 4, 4, 4, 5, 5, '["HISTORICAL_CONTEXT", "EXAMPLE", "SOCIAL_CRITIQUE"]'::jsonb, '["apagamento histórico", "racismo", "memória coletiva"]'::jsonb, '["racismo", "memória", "escravidão", "identidade", "apagamento histórico"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
