VALUES ('REP-048', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Bruno Bioni', NULL, 'JURISTA / PESQUISADOR', 'Privacidade, proteção de dados e regulação digital', 'Brasil', 'Sua produção permite discutir proteção de dados para além do consentimento individual, incluindo responsabilização, governança e limites do tratamento de dados em ecossistemas digitais.', 'Especialista brasileiro em proteção de dados: ajuda a explicar por que consentimento isolado nem sempre basta em ambientes marcados por assimetria de informação e tratamento massivo de dados.', 'Use quando o problema envolver coleta, circulação ou uso de dados e a responsabilidade de organizações e plataformas.', 'A produção de Bruno Bioni ajuda a compreender que a proteção de dados não pode depender apenas de decisões individuais de consentimento, pois sistemas digitais envolvem assimetrias de informação e responsabilidades institucionais.', 'Não usar proteção de dados como sinônimo de sigilo absoluto ou proibição de qualquer tratamento de dados.', 'MEDIUM', 'INTERMEDIATE', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["DEFINE_CONCEPT", "LEGAL_GAP", "SUPPORT_INTERVENTION"]'::jsonb, '[]'::jsonb, '["privacidade", "proteção de dados", "plataformas", "IA", "assimetria informacional"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
