VALUES ('REP-049', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Fernanda Bruno', NULL, 'PESQUISADORA', 'Vigilância, tecnologia, subjetividade e visibilidade', 'Brasil', 'Pesquisa como tecnologias de vigilância e visibilidade reorganizam relações de poder, comportamentos e subjetividades em ambientes digitais.', 'Fernanda Bruno ajuda a entender vigilância digital como processo social: tecnologias coletam, observam e classificam comportamentos, afetando visibilidade, poder e autonomia.', 'Use quando o argumento precisa explicar como monitoramento e coleta de rastros digitais produzem relações de poder, e não apenas riscos abstratos de privacidade.', 'Os estudos de Fernanda Bruno permitem compreender que a vigilância digital não se limita a câmeras ou espionagem direta, pois também ocorre pela coleta e classificação cotidiana de rastros produzidos nas plataformas.', 'Não equiparar toda coleta de dados a uma mesma forma de vigilância; explique o mecanismo e a finalidade.', 'MEDIUM', 'INTERMEDIATE', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["DEFINE_CONCEPT", "SOCIAL_CRITIQUE", "EXPLAIN_CAUSE"]'::jsonb, '[]'::jsonb, '["vigilância digital", "rastreamento", "plataformas", "visibilidade", "dados"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
