VALUES ('REP-050', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Sérgio Amadeu da Silveira', NULL, 'PESQUISADOR / CIENTISTA POLÍTICO', 'Sistemas algorítmicos, IA, soberania digital e tecnopolítica', 'Brasil', 'Pesquisa implicações tecnopolíticas de sistemas algorítmicos e IA, incluindo classificação, modulação, privacidade, soberania de dados e efeitos políticos.', 'Sistemas algorítmicos não são apenas ferramentas neutras: classificam, ordenam e modulam informações e escolhas conforme dados, objetivos e critérios definidos em seu desenho.', 'Use para mostrar mecanismos concretos da IA e dos algoritmos, evitando frases vagas como “a tecnologia muda tudo”.', 'As pesquisas de Sérgio Amadeu ajudam a compreender que sistemas algorítmicos não apenas exibem conteúdos, mas classificam e ordenam informações segundo critérios capazes de influenciar visibilidade e decisão.', 'Não afirmar que todo algoritmo é necessariamente discriminatório; o risco depende de dados, objetivos, desenho e contexto.', 'HIGH', 'INTERMEDIATE', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["DEFINE_CONCEPT", "EXPLAIN_CAUSE", "SOCIAL_CRITIQUE"]'::jsonb, '[]'::jsonb, '["algoritmos", "IA", "discriminação algorítmica", "desinformação", "soberania de dados"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
