VALUES ('REP-051', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Rodolfo Rorato Londero', 'publicidade infantil e atenção no YouTube', 'PESQUISADOR / ESTUDO', 'Comunicação, publicidade infantil e atenção', 'Brasil', 'Estudo de conteúdo no YouTube mostrou como product placement pode integrar publicidade à narrativa infantil, dificultando que crianças reconheçam a mensagem comercial como publicidade.', 'Na publicidade infantil digital, anúncios podem aparecer dentro da própria narrativa; isso dificulta a identificação da intenção comercial e explora a atenção infantil.', 'Use para explicar mecanismos específicos de persuasão no ambiente digital infantil.', 'O estudo de Rodolfo Londero e Meire Sebastião sobre publicidade infantil no YouTube mostra que o product placement pode tornar a intenção comercial menos identificável para a criança ao ser inserido na própria narrativa do vídeo.', 'Não generalizar os resultados do recorte analisado para todo conteúdo infantil de todas as plataformas.', 'MEDIUM', 'BASIC', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["EXPLAIN_CAUSE", "PROVE_PROBLEM", "SOCIAL_CRITIQUE"]'::jsonb, '[]'::jsonb, '["publicidade infantil", "economia da atenção", "YouTube", "consumo", "influenciadores mirins"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
