VALUES ('REP-052', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Nise da Silveira', NULL, 'PSIQUIATRA / PESQUISADORA', 'Saúde mental, terapêutica ocupacional e cuidado humanizado', 'Brasil', 'Nise se opôs a práticas psiquiátricas agressivas e desenvolveu formas de cuidado baseadas em atividades expressivas, convivência e portas abertas, criando a Seção de Terapêutica Ocupacional, o Museu de Imagens do Inconsciente e a Casa das Palmeiras.', 'Nise da Silveira é referência brasileira de cuidado psiquiátrico humanizado: combateu práticas agressivas e valorizou expressão, vínculo e reabilitação em liberdade.', 'Use para contextualizar historicamente alternativas ao modelo asilar e mostrar que cuidado em saúde mental pode preservar expressão e autonomia.', 'A trajetória de Nise da Silveira mostra que o tratamento psiquiátrico pode ser reorganizado a partir de vínculo, expressão e respeito à pessoa, em oposição a práticas institucionalizantes e violentas.', 'Não atribuir a Nise toda a Reforma Psiquiátrica brasileira nem dizer que arte, isoladamente, substitui qualquer tratamento clínico.', 'MEDIUM', 'BASIC', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["HISTORICAL_CONTEXT", "EXAMPLE", "SUPPORT_INTERVENTION"]'::jsonb, '[]'::jsonb, '["institucionalização", "estigma", "cuidado em liberdade", "tratamento desumanizado"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
