VALUES ('REP-053', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Paulo Amarante', NULL, 'PSIQUIATRA / PESQUISADOR', 'Reforma psiquiátrica, saúde mental e atenção psicossocial', 'Brasil', 'Pioneiro da Reforma Psiquiátrica brasileira, diferencia desinstitucionalização de mera desospitalização e enfatiza direitos, território, participação social e cuidado em liberdade.', 'Paulo Amarante: reforma psiquiátrica não é só fechar hospitais; envolve criar outro modelo de cuidado, com direitos, território, serviços comunitários e participação social.', 'Use para explicar a transformação do modelo de cuidado e seus desafios atuais.', 'A noção de desinstitucionalização trabalhada por Paulo Amarante mostra que reformar a assistência psiquiátrica exige mais do que reduzir internações: é preciso construir redes territoriais de cuidado e reconhecimento de direitos.', 'Não confundir desinstitucionalização com abandono de pessoas ou ausência de cuidado intensivo quando necessário.', 'HIGH', 'INTERMEDIATE', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["DEFINE_CONCEPT", "HISTORICAL_CONTEXT", "SUPPORT_INTERVENTION"]'::jsonb, '[]'::jsonb, '["RAPS", "institucionalização", "estigma", "cuidado em liberdade", "políticas de saúde mental"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
