VALUES ('REP-054', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'André Luiz Freitas Dias', NULL, 'PESQUISADOR / EXTENSIONISTA', 'Políticas públicas e população em situação de rua', 'Brasil', 'Coordena o Observatório Brasileiro de Políticas Públicas com a População em Situação de Rua (OBPopRua/POLOS-UFMG), produzindo pesquisas e monitoramento sobre perfil, violência e políticas públicas.', 'Pesquisador da UFMG especializado em população em situação de rua; ajuda a conectar invisibilidade social a dados, violência, saúde, documentação e desenho de políticas públicas.', 'Use para sair de uma abordagem abstrata da invisibilidade e trabalhar condições concretas e políticas voltadas à população em situação de rua.', 'O trabalho do OBPopRua, coordenado por André Dias, mostra que a população em situação de rua precisa ser tratada como público específico de políticas intersetoriais, com dados próprios sobre moradia, saúde, documentação e violência.', 'Não tratar estimativas baseadas em CadÚnico como censo completo da população em situação de rua.', 'MEDIUM', 'BASIC', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["PROVE_PROBLEM", "SHOW_INVISIBILITY", "SUPPORT_INTERVENTION"]'::jsonb, '[]'::jsonb, '["população em situação de rua", "violência", "documentação", "saúde", "moradia", "políticas públicas"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
