VALUES ('REP-055', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Ailton Krenak', NULL, 'INTELECTUAL / ESCRITOR INDÍGENA', 'Direitos indígenas, cultura, território e pensamento socioambiental', 'Brasil', 'Intelectual Krenak e liderança histórica do movimento indígena, articulou direitos constitucionais e produz reflexão sobre modos de vida, natureza, desenvolvimento e diversidade cultural.', 'Krenak ajuda a questionar a ideia de natureza como mero recurso e a relacionar território, cultura e continuidade da vida dos povos originários.', 'Use em temas que envolvam território e ambiente quando for importante incorporar perspectiva indígena, e não apenas falar sobre indígenas a partir de fora.', 'A reflexão de Ailton Krenak permite questionar modelos de desenvolvimento que separam sociedade e natureza, especialmente quando a exploração territorial ameaça modos de vida e continuidade cultural de povos originários.', 'Não transformar Krenak em “ambientalista genérico”; preserve a dimensão indígena, territorial, histórica e cultural de sua obra.', 'MEDIUM', 'INTERMEDIATE', 'MEDIUM', NULL, NULL, NULL, NULL, NULL, NULL, '["SOCIAL_CRITIQUE", "DEFINE_CONCEPT", "HISTORICAL_CONTEXT"]'::jsonb, '[]'::jsonb, '["direitos indígenas", "território", "cultura", "meio ambiente", "desenvolvimento", "memória"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
