VALUES ('REP-056', 'PERSON', 'REPERTOIRE', '[]'::jsonb, 'Davi Kopenawa Yanomami', NULL, 'LIDERANÇA / INTELECTUAL INDÍGENA', 'Território Yanomami, floresta, cosmologia e direitos indígenas', 'Brasil', 'Xamã e presidente da Hutukara Associação Yanomami, autor com Bruce Albert de A Queda do Céu. Sua produção articula cosmologia Yanomami, crítica à destruição ambiental e defesa territorial.', 'Kopenawa fala a partir do pensamento Yanomami: território e floresta não são apenas recursos econômicos, mas condições de existência cultural, espiritual e coletiva.', 'Use para incorporar uma voz indígena diretamente afetada por invasões territoriais e destruição ambiental.', 'O pensamento de Davi Kopenawa evidencia que a destruição da floresta não é apenas perda ambiental: para povos como os Yanomami, ela ameaça simultaneamente território, saúde, memória e continuidade cultural.', 'Não reduzir a cosmologia Yanomami a metáfora ambiental ocidental nem usar Kopenawa como representante de todos os povos indígenas.', 'HIGH', 'INTERMEDIATE', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["SOCIAL_CRITIQUE", "HISTORICAL_CONTEXT", "EXAMPLE"]'::jsonb, '[]'::jsonb, '["garimpo", "território", "floresta", "saúde indígena", "violência", "memória"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
    ON CONFLICT (codigo) DO UPDATE SET tipo_entidade = EXCLUDED.tipo_entidade, papel = EXCLUDED.papel, tipos_evidencia = EXCLUDED.tipos_evidencia, nome = EXCLUDED.nome, subtitulo = EXCLUDED.subtitulo, tipo_descricao = EXCLUDED.tipo_descricao, area = EXCLUDED.area, pais = EXCLUDED.pais, ideia_central = EXCLUDED.ideia_central, lembre_na_prova = EXCLUDED.lembre_na_prova, como_usar = EXCLUDED.como_usar, exemplo_aplicacao = EXCLUDED.exemplo_aplicacao, erro_comum = EXCLUDED.erro_comum, risco_uso = EXCLUDED.risco_uso, dificuldade = EXCLUDED.dificuldade, saturacao = EXCLUDED.saturacao, nota_versatilidade = EXCLUDED.nota_versatilidade, nota_autoridade = EXCLUDED.nota_autoridade, nota_compreensao = EXCLUDED.nota_compreensao, nota_aplicabilidade = EXCLUDED.nota_aplicabilidade, nota_especificidade = EXCLUDED.nota_especificidade, nota_originalidade = EXCLUDED.nota_originalidade, funcoes_argumentativas = EXCLUDED.funcoes_argumentativas, tipos_argumento = EXCLUDED.tipos_argumento, tags = EXCLUDED.tags, populacao = EXCLUDED.populacao, ano_evidencia = EXCLUDED.ano_evidencia, status_verificacao = EXCLUDED.status_verificacao, verificado_em = EXCLUDED.verificado_em, ativo = EXCLUDED.ativo;
