VALUES ('REP-057', 'CULTURAL_WORK', 'REPERTOIRE', '[]'::jsonb, 'A Queda do Céu', 'Davi Kopenawa e Bruce Albert', 'OBRA LITERÁRIA / AUTOETNOGRAFIA', 'Cosmologia Yanomami, ambiente, território e contato interétnico', 'Brasil', 'Relato de vida, autoetnografia e manifesto cosmopolítico que apresenta pensamento Yanomami e critica processos de destruição territorial e ambiental associados ao contato e à exploração.', 'A Queda do Céu permite discutir território e ambiente a partir da visão Yanomami, evitando tratar povos indígenas apenas como objeto externo de estudo.', 'Use para dar base cultural e indígena a argumentos sobre território, destruição ambiental e modelos de desenvolvimento.', 'Em A Queda do Céu, a crítica de Davi Kopenawa ao “povo da mercadoria” permite confrontar modelos de exploração que tratam a floresta somente como recurso, ignorando vínculos territoriais e cosmológicos indígenas.', 'Não apresentar a obra como descrição de todos os povos indígenas; ela é situada no universo Yanomami.', 'HIGH', 'ADVANCED', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["EXAMPLE", "SOCIAL_CRITIQUE", "HISTORICAL_CONTEXT"]'::jsonb, '[]'::jsonb, '["território", "garimpo", "meio ambiente", "cultura", "memória", "colonialismo"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
