VALUES ('REP-058', 'CULTURAL_WORK', 'REPERTOIRE', '[]'::jsonb, 'Chuva é Cantoria na Aldeia dos Mortos', NULL, 'FILME', 'Identidade indígena, cidade, cultura e pertencimento', 'Brasil', 'O filme acompanha Ihjãc, jovem Krahô que se afasta da aldeia e enfrenta na cidade dificuldades ligadas à identidade, pertencimento e vida indígena contemporânea.', 'Filme sobre um jovem Krahô entre aldeia, ritual, cidade e identidade; útil para evitar a representação de povos indígenas como figuras apenas do passado.', 'Use para discutir indígenas no Brasil contemporâneo, tensões entre cidade e território e preservação cultural sem congelar identidades.', 'Chuva é Cantoria na Aldeia dos Mortos apresenta um jovem Krahô vivendo dilemas contemporâneos entre cidade, ritual e pertencimento, o que ajuda a romper a imagem de povos indígenas como grupos presos ao passado.', 'Não usar o filme como retrato de todos os povos indígenas nem como documentário estatístico.', 'LOW', 'BASIC', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["EXAMPLE", "COMPARE_REALITY", "SOCIAL_CRITIQUE"]'::jsonb, '[]'::jsonb, '["identidade", "pertencimento", "cultura", "cidade", "direitos indígenas"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
