VALUES ('REP-061', 'CULTURAL_WORK', 'REPERTOIRE', '[]'::jsonb, 'Aquarius', 'Kleber Mendonça Filho', 'FILME', 'Envelhecimento, autonomia, memória e cidade', 'Brasil', 'Clara, mulher de 65 anos, resiste à pressão de uma construtora para deixar o apartamento onde construiu parte de sua história, articulando envelhecimento, memória, autonomia e especulação imobiliária.', 'Aquarius combina envelhecimento e cidade: uma mulher idosa é sujeito autônomo de desejo, memória e decisão, e resiste à pressão econômica sobre seu espaço de vida.', 'Use para discutir envelhecimento sem reduzir idosos a dependência e para conectar autonomia pessoal a território e memória.', 'Em Aquarius, a resistência de Clara à pressão imobiliária evidencia que envelhecimento não elimina autonomia, desejo ou vínculo territorial, além de mostrar como o espaço urbano também guarda memória e identidade.', 'Não transformar o filme em retrato geral da velhice brasileira; é um exemplo cultural situado.', 'LOW', 'BASIC', 'LOW', NULL, NULL, NULL, NULL, NULL, NULL, '["EXAMPLE", "SOCIAL_CRITIQUE", "SHOW_INEQUALITY"]'::jsonb, '[]'::jsonb, '["etarismo", "autonomia", "memória", "especulação imobiliária", "direito à cidade"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
