VALUES ('REP-062', 'CULTURAL_WORK', 'REPERTOIRE', '[]'::jsonb, 'Central do Brasil', 'Walter Salles', 'FILME', 'Analfabetismo, letramento e cidadania', 'Brasil', 'Dora escreve cartas para pessoas analfabetas na estação Central do Brasil, tornando visível como a ausência de domínio da escrita pode criar dependência de intermediários para comunicação e exercício cotidiano da cidadania.', 'A cena das cartas permite relacionar analfabetismo a autonomia e cidadania: quem não domina a escrita pode depender de terceiros para registrar voz, vínculos e direitos.', 'Use junto a Magda Soares para transformar alfabetização em questão de participação social, não apenas decodificação.', 'Em Central do Brasil, a dependência de pessoas analfabetas de uma intermediária para escrever cartas evidencia como a exclusão da cultura escrita pode restringir autonomia e participação social.', 'Não usar o filme como dado sobre a taxa atual de analfabetismo; ele é repertório cultural.', 'LOW', 'BASIC', 'MEDIUM', NULL, NULL, NULL, NULL, NULL, NULL, '["EXAMPLE", "SHOW_INEQUALITY", "SOCIAL_CRITIQUE"]'::jsonb, '[]'::jsonb, '["analfabetismo", "letramento", "cidadania", "desigualdade regional"]'::jsonb, NULL, NULL, 'VERIFIED', '2026-10-07', TRUE)
